// #bb57bd מסך אשף Onboarding (/onboarding) — порядок шагов, индикатор, вперёд/назад, «שמירה והמשך מאוחר יותר»,
// состояние сохранения, завершение. Кейсы: .qa/tests/onboarding-wizard/OW-01..OW-06. План: specs/onboarding-wizard.md.
// 15.11.2026: OW-04 обновлён под TAQO (черновик → лента с карточкой «הגדרת החשבון»). Остальные тесты файла написаны
// под мастер до TAQO (заголовок «שלב N מתוך 4: …», «הבא», «סיום והקמת הפרופיל», ✓) — на регрессе ожидаемо упадут
// как ОШИБКА ТЕСТА; их нужно перегенерировать по живому мастеру TAQO.
// ADMIN компании A (.qa/auth/admin.json). ДАННЫЕ ПРОФИЛЯ НЕ МЕНЯЮТСЯ: все POST company_profiles перехватываются
// и на сервер не уходят (wizard-mock.ts), прочие записи в Supabase прерываются; в конце каждого теста — проверка, что
// перехвачено всё. Поэтому без @data; @prod-safe.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import {
  FINISH, SAVE_LATER, SAVING, STEPS, TAQO_CONTINUE_SETUP, TAQO_NEXT, TAQO_SAVED, TAQO_SAVE_LATER, TAQO_SETUP_CARD,
  btn, clickAndSave, clickAndSaveTaqo, expectDone, expectStep, expectTaqoStep, mockWizardServer, stepHeading,
} from './wizard-mock';

test.use({ storageState: authState('admin') });

test.describe('אשף Onboarding — ניווט והתקדמות', () => {
  test('השלבים מוצגים ברצף 1→4 עם "שלב N מתוך 4", aria-current בשלב הנוכחי ו-✓ בשלבים שהושלמו #bb57bd @desktop @prod-safe', async ({ page }) => {
    // OW-01 + OW-02: мастер «как у новой компании» (в ответе сервера onboarding сброшен только для этого окна).
    const server = await mockWizardServer(page, { fresh: true });
    await page.goto('/onboarding');
    await expect(page.getByRole('heading', { name: 'הקמת פרופיל החברה', level: 1 })).toBeVisible();

    await expectStep(page, 1);
    await expectDone(page, []);
    await expect(btn(page, 'הקודם')).toBeDisabled();

    for (let n = 1; n <= 3; n++) {
      await clickAndSave(page, server, 'הבא');
      await expectStep(page, n + 1);
      await expectDone(page, Array.from({ length: n }, (_, i) => i + 1));
      // В сохранении: следующий шаг (0-based) и пройденные шаги.
      expect(server.lastOnboarding()).toMatchObject({ step: n, completed: false, completedSteps: Array.from({ length: n }, (_, i) => i) });
    }
    // Последний шаг: вместо «הבא» — «סיום והקמת הפרופיל».
    await expect(btn(page, 'הבא')).toHaveCount(0);
    await expect(btn(page, FINISH)).toBeEnabled();
    expect(server.blockedWrites).toEqual([]);
  });

  test('מעבר קדימה ואחורה בין השלבים בלי לאבד נתונים שהוזנו #bb57bd @desktop @prod-safe', async ({ page }) => {
    // OW-03: правки только в окне браузера, сохранения перехвачены.
    const server = await mockWizardServer(page, { fresh: true });
    const years = page.getByRole('textbox', { name: 'ותק — מספר שנות פעילות' });
    const experience = page.getByRole('textbox', { name: 'ניסיון החברה' });
    const exp = `QA-AUTO ניסיון ${Date.now()}`;

    await page.goto('/onboarding');
    await expectStep(page, 1);
    await clickAndSave(page, server, 'הבא');
    await expectStep(page, 2);

    await years.fill('37');
    await experience.fill(exp);

    await clickAndSave(page, server, 'הבא');
    await expectStep(page, 3);
    expect(server.saves.at(-1)?.details).toMatchObject({ matching: { years_active: '37', experience: exp } });

    await clickAndSave(page, server, 'הקודם');
    await expectStep(page, 2);
    await expect(years).toHaveValue('37');
    await expect(experience).toHaveValue(exp);

    await clickAndSave(page, server, 'הקודם');
    await expectStep(page, 1);
    await clickAndSave(page, server, 'הבא');
    await expectStep(page, 2);
    await expect(years).toHaveValue('37');
    await expect(experience).toHaveValue(exp);
    // Возврат назад не снимает ✓ с пройденных шагов (реджект rej_fa77ad6f).
    await expectDone(page, [1, 2, 3]);
    expect(server.blockedWrites).toEqual([]);
  });

  test('"שמור והמשך מאוחר יותר" מעביר לפיד עם "ההתקדמות נשמרה" וכרטיס "הגדרת החשבון"; "המשך הגדרה" חוזר לאותו שלב #bb57bd @desktop @prod-safe', async ({ page }) => {
    // OW-04 (обновлён 15.11.2026 под TAQO, commit 103dd3f): черновик теперь ведёт в ленту с карточкой «הגדרת החשבון»,
    // а не остаётся в мастере. Сохранения перехвачены (wizard-mock), данные компании A не меняются.
    const server = await mockWizardServer(page, { fresh: true });
    await page.goto('/onboarding');
    await expectTaqoStep(page, 1);
    await clickAndSaveTaqo(page, server, TAQO_NEXT);
    await expectTaqoStep(page, 2);
    await clickAndSaveTaqo(page, server, TAQO_NEXT);
    await expectTaqoStep(page, 3);

    await clickAndSaveTaqo(page, server, TAQO_SAVE_LATER);
    await page.waitForURL((u) => u.pathname === '/');
    await expect(page.getByText(TAQO_SAVED, { exact: true })).toBeVisible();
    // Карточка «הגדרת החשבון»: пройдено 2 из 4 шагов (пройдены 1–2, текущий — 3).
    await expect(page.getByText(TAQO_SETUP_CARD, { exact: true })).toBeVisible();
    await expect(page.getByText(/^\s*2\s*\/\s*4\s*$/)).toBeVisible();

    const cont = page.getByRole('link', { name: TAQO_CONTINUE_SETUP }).or(page.getByRole('button', { name: TAQO_CONTINUE_SETUP }));
    await cont.first().click();
    await page.waitForURL((u) => u.pathname === '/onboarding');
    await expectTaqoStep(page, 3);
    expect(server.blockedWrites).toEqual([]);
  });

  test('בזמן שמירת שלב הכפתורים מושבתים ועל הכפתור מוצג "שומר…" #bb57bd @desktop @prod-safe', async ({ page }) => {
    // OW-05: ответ на сохранение держим, пока не проверено состояние (без фиксированной паузы).
    const server = await mockWizardServer(page, { fresh: true });
    await page.goto('/onboarding');
    await expectStep(page, 1);

    const gate = server.hold();
    try {
      await btn(page, 'הבא').click();
      await expect(btn(page, SAVING)).toBeVisible();
      await expect(btn(page, SAVING)).toBeDisabled();
      await expect(btn(page, 'הקודם')).toBeDisabled();
      await expect(btn(page, SAVE_LATER)).toBeDisabled();
      await expect(stepHeading(page)).toHaveText(`שלב 1 מתוך 4: ${STEPS[0]}`);
    } finally {
      gate.release();
    }
    await expectStep(page, 2);
    await expect(btn(page, SAVING)).toHaveCount(0);
    await expect(btn(page, 'הבא')).toBeEnabled();
    expect(server.blockedWrites).toEqual([]);
  });

  test('"סיום והקמת הפרופיל" מסמן את כל השלבים כהושלמו ומעביר לדף הבית #bb57bd @desktop @prod-safe', async ({ page }) => {
    // OW-06
    const server = await mockWizardServer(page, { fresh: true });
    await page.goto('/onboarding');
    await expectStep(page, 1);
    for (let n = 1; n <= 3; n++) await clickAndSave(page, server, 'הבא');
    await expectStep(page, 4);

    const gate = server.hold();
    try {
      await btn(page, FINISH).click();
      await expect(btn(page, SAVING)).toBeDisabled();
    } finally {
      gate.release();
    }
    await page.waitForURL((u) => u.pathname === '/');
    await expect(page.getByRole('heading', { name: 'פיד מכרזים', level: 1 })).toBeVisible();
    expect(server.lastOnboarding()).toMatchObject({ completed: true, completedSteps: [0, 1, 2, 3] });

    // После завершения у всех 4 шагов ✓ (реджект rej_fa77ad6f).
    await page.goto('/onboarding');
    await expect(stepHeading(page)).toBeVisible();
    await expectDone(page, [1, 2, 3, 4]);
    expect(server.blockedWrites).toEqual([]);
  });
});

test.describe('אשף Onboarding — השלב השמור בשרת (קריאה בלבד)', () => {
  test('פתיחת /onboarding ממשיכה מהשלב השמור בפרופיל החברה, ✓ לפי השלבים שהושלמו #bb57bd @desktop @prod-safe', async ({ page }) => {
    // OW-07: ничего не нажимаем; на всякий случай любые записи прерываются.
    const writes: string[] = [];
    await page.route(/supabase\.co\/(rest|storage)\/v1\//, (route) => {
      const r = route.request();
      if (['GET', 'HEAD', 'OPTIONS'].includes(r.method())) return route.fallback();
      writes.push(`${r.method()} ${r.url()}`);
      return route.abort();
    });
    const profile = page.waitForResponse((r) => /\/rest\/v1\/company_profiles\?/.test(r.url()) && r.request().method() === 'GET' && r.ok());
    await page.goto('/onboarding');
    const rows = (await (await profile).json()) as { details?: { onboarding?: { step: number; completedSteps?: number[] } } }[];
    const ob = rows[0]?.details?.onboarding;
    expect(ob, 'в профиле компании A нет details.onboarding').toBeTruthy();

    await expectStep(page, ob!.step + 1);
    await expectDone(page, (ob!.completedSteps ?? []).map((i) => i + 1));
    expect(writes).toEqual([]);
  });
});
